'use strict';let deferredInstall=null;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e;showInstall();});function showInstall(){if(document.getElementById('pwa-install'))return;const top=document.querySelector('.top');if(!top||!deferredInstall)return;const b=document.createElement('button');b.id='pwa-install';b.className='pwa-button';b.textContent='Instalovat';b.onclick=async()=>{await deferredInstall.prompt();deferredInstall=null;b.remove();};top.appendChild(b);}async function registerSW(){if(!('serviceWorker'in navigator))return;try{await navigator.serviceWorker.register('./service-worker.js');}catch(e){console.warn('SW',e);}}function allPhotoUrls(){if(!window.ATLAS)return[];const out=[];for(const p of window.ATLAS.plants||[])for(const im of p.images||[]){if(im.path)out.push(im.path);if(im.thumb&&im.thumb!==im.path)out.push(im.thumb);}return[...new Set(out)];}function addOfflineButton(){const bar=document.querySelector('.results-bar');if(!bar||document.getElementById('pwa-offline'))return;const wrap=document.createElement('span');const b=document.createElement('button');b.id='pwa-offline';b.className='pwa-button';b.textContent='⬇ Fotky offline';const s=document.createElement('span');s.className='pwa-status';wrap.append(b,s);bar.prepend(wrap);b.onclick=async()=>{const reg=await navigator.serviceWorker.ready;const sw=navigator.serviceWorker.controller||reg.active;if(!sw)return;s.textContent='Čekám…';b.disabled=true;sw.postMessage({type:'CACHE_PHOTOS',urls:allPhotoUrls()});};navigator.serviceWorker?.addEventListener('message',e=>{if(e.data?.type==='CACHE_PROGRESS')s.textContent=e.data.done+'/'+e.data.total;if(e.data?.type==='CACHE_DONE'){s.textContent='Fotky jsou offline';b.textContent='✓ Fotky offline';b.disabled=true;}if(e.data?.type==='CACHE_ERROR'){s.textContent='Stažení se nepodařilo';b.disabled=false;}});}window.addEventListener('DOMContentLoaded',()=>{registerSW();addOfflineButton();});
